  val remoteId: String,
  val name: String,
  val isFavourite: Boolean = false,   // local only: a blind upsert would reset it
  val isDirty: Boolean = false
)

@Dao
interface ContactDao {
  // ❌ drops the new values when the row already exists; -1 marks each skipped row
  @Insert(onConflict = OnConflictStrategy.IGNORE)
  suspend fun insertIgnoring(rows: List<ContactEntity>): List<Long>

  // ❌ DELETE + INSERT: cascades fire, generated ids change, omitted columns reset
  @Insert(onConflict = OnConflictStrategy.REPLACE)
  suspend fun insertReplacing(rows: List<ContactEntity>)

  // ✅ insert, or update the existing row in place
  @Upsert
  suspend fun upsert(rows: List<ContactEntity>)

  // Merge explicitly when local-only columns must survive the sync
  @Query("UPDATE contact SET name = :name WHERE remoteId = :remoteId")
  suspend fun rename(remoteId: String, name: String): Int
}

// "created" or "already there", without a second query
suspend fun saveIfNew(row: ContactEntity): Boolean =
  dao.insertIgnoring(listOf(row)).single() != -1L

// A sync that must not clobber local state
suspend fun applyRemote(remote: List<ContactDto>) = db.withTransaction {
  remote.forEach { dto -> dao.rename(dto.id, dto.name) }
  dao.upsert(remote.filterNot { dao.exists(it.id) }.map { it.toEntity() })
}

