// Or file it into Downloads automatically, through MediaStore
suspend fun saveToDownloads(
  context: Context,
  name: String,
  write: (OutputStream) -> Unit
): Uri? = withContext(Dispatchers.IO) {
  val resolver = context.contentResolver
  val values = ContentValues().apply {
    put(MediaStore.Downloads.DISPLAY_NAME, name)
    put(MediaStore.Downloads.MIME_TYPE, "application/pdf")
    put(MediaStore.Downloads.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/Statements")
    put(MediaStore.Downloads.IS_PENDING, 1)          // hidden until it is complete
  }
  val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)
    ?: return@withContext null
  resolver.openOutputStream(uri)?.use(write)
  resolver.update(uri, ContentValues().apply { put(MediaStore.Downloads.IS_PENDING, 0) }, null, null)
  uri
}

