// ✅ AtomicFile: writes a side file, syncs it, renames over the target
private val cart = AtomicFile(File(context.filesDir, "cart.json"))

suspend fun save(json: String) = withContext(Dispatchers.IO) {
  val out = cart.startWrite()
  try {
    out.write(json.toByteArray())
    cart.finishWrite(out)            // flush + fsync + atomic rename
  } catch (e: IOException) {
    cart.failWrite(out)              // target keeps the last good bytes
    throw e
  }
}

suspend fun load(): String? = withContext(Dispatchers.IO) {
  runCatching { cart.readFully().decodeToString() }.getOrNull()
}

// The same dance by hand, when the bytes are not going through AtomicFile
fun writeAtomically(target: File, bytes: ByteArray) {
  val tmp = File(target.parentFile, target.name + ".tmp")   // same filesystem
  FileOutputStream(tmp).use { out ->
    out.write(bytes)
    out.fd.sync()                    // rename orders metadata, not your data
  }
  check(tmp.renameTo(target))
}

