  override fun migrate(db: SupportSQLiteDatabase) {
    db.execSQL("ALTER TABLE task ADD COLUMN priority INTEGER NOT NULL DEFAULT 0")
    db.execSQL("CREATE INDEX IF NOT EXISTS index_task_priority ON task(priority)")
  }
}

