  helper.createDatabase(TEST_DB, 3).use { db ->
    db.execSQL("INSERT INTO task (id, title) VALUES (1, 'buy milk')")
  }
  // throws if the migrated schema differs from schemas/4.json
  helper.runMigrationsAndValidate(TEST_DB, 4, true, MIGRATION_3_4)
}

// ❌ 300 rows, 300 transactions, 300 invalidation signals, 300 re-queries
suspend fun applyRemoteBad(rows: List<TaskEntity>) {
  rows.forEach { dao.upsert(it) }
}

// ✅ one commit, one notification, and nobody observes a half-applied sync
suspend fun applyRemote(rows: List<TaskEntity>) = db.withTransaction {
  dao.deleteMissing(rows.map { it.id })
  dao.upsert(rows)
}

@Dao
interface TaskDao {
  // The same batching, expressed on the DAO
  @Transaction
  suspend fun replaceAll(rows: List<TaskEntity>) {
    deleteAll()
    upsert(rows)
  }

  // Invalidated just as often as SELECT *, but far cheaper to re-run
  @Query("SELECT * FROM task WHERE done = 0 ORDER BY dueAt LIMIT 50")
  fun observeOpen(): Flow<List<TaskEntity>>
}

// Saves the recomposition, not the query: the SELECT has already executed
val open = dao.observeOpen().distinctUntilChanged()

// Only writes through THIS instance are tracked; two processes need this
Room.databaseBuilder(context, AppDatabase::class.java, "app.db")
  .enableMultiInstanceInvalidation()
  .build()

// React to "the table changed" without running a query at all
db.invalidationTracker.addObserver(object : InvalidationTracker.Observer(arrayOf("task")) {
  override fun onInvalidated(tables: Set<String>) = scheduleUpload()
})

// ❌ hangs forever: the DAO call leaves the transaction thread, then blocks
// waiting for a database held by the transaction that is waiting for it
suspend fun saveBad(order: Order) = db.withTransaction {
  withContext(Dispatchers.IO) { orderDao.insert(order.toEntity()) }
  lineDao.insertAll(order.lines.map { it.toEntity() })
}

// ❌ also fatal: runBlocking on the transaction thread, plus a network call
// that holds the write lock for the length of the request
suspend fun saveWorse(id: String) = db.withTransaction {
  val fresh = api.fetchOrder(id)
  runBlocking { orderDao.insert(fresh.toEntity()) }
}

// ✅ I/O first; then a short transaction of suspend DAO calls and nothing else
suspend fun save(id: String) {
  val fresh = api.fetchOrder(id)              // network outside the transaction
  db.withTransaction {
    orderDao.insert(fresh.toEntity())
    lineDao.insertAll(fresh.lines.map { it.toEntity() })
  }                                           // commits here, then Flows emit once
}

// The annotation route: Room wraps the whole method body in one transaction
@Dao
interface OrderDao {
  @Transaction
  suspend fun replace(order: OrderEntity, lines: List<LineEntity>) {
    deleteLines(order.id)
    insert(order)
    insertLines(lines)
  }
}

// Keystore-sealed bytes belong where backup and restore cannot reach them
private val sealed = File(context.noBackupFilesDir, "session.bin")

// ...and the read must still survive backups written before that fix shipped
fun loadToken(): String? = try {
  crypto.decrypt(sealed.readBytes())
} catch (e: GeneralSecurityException) {   // key absent: restored on another device
  reset()
  null
} catch (e: IOException) {
  null
}

private fun reset() {
  sealed.delete()
  crypto.deleteKeyEntry()                 // drop the dangling Keystore alias too
}

// A marker in no-backup storage never returns from a restore, so a populated
// database beside a missing marker means "these files came from another phone"
class RestoreDetector(private val context: Context) {
  private val marker = File(context.noBackupFilesDir, "install.marker")

  fun isRestoredInstall(): Boolean =
    !marker.exists() && context.getDatabasePath("app.db").exists()

  fun markInstalled() = marker.writeText(System.currentTimeMillis().toString())
}

suspend fun onAppStart() = withContext(Dispatchers.IO) {
  if (detector.isRestoredInstall()) {
    db.clearAllTables()                   // previous device's rows, no valid session
    reset()
  }
  detector.markInstalled()
}
